178	        // Soft-match: the identity key differs, yet the surname's soundex and the postcode match an
179	        // existing owner, flagged 'possibleDuplicate'. This is exactly the same lastName/postcode,
180	        // different telephone case that is no longer a hard duplicate.
181	        Integer possibleDuplicateOf = this.clinicService.findPossibleDuplicateOwnerId(owner);
182	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
183	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
184	        owner.setNamesakeCount(
185	            this.clinicService.countOwnersByName(owner.getFirstName(), owner.getLastName()));
186	        this.clinicService.saveOwner(owner);
187	        this.clinicService.registerIdempotencyKey(idempotencyKey, owner.getId());
188	        OwnerDto ownerDto = toOwnerDtoWithDerived(owner);
189	        auditLogger.info(
190	            "owner created: id={} memberId={} registrationDate={} membershipLevel={}",
191	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
192	            ownerDto.getMembershipLevel());
193	        // Immutable structured event, in addition to the human-readable line above. It carries the
194	        // owner's primary identifier (Owner#primaryIdentifier), i.e. its unified memberId.
195	        this.ownerAuditEvents.ownerCreated(
196	            owner.getId(), owner.primaryIdentifier(), ownerDto.getMembershipLevel());
197	        // Enqueue a welcome notification for the freshly created owner: the NOTIFY line
198	        // carries the owner id and its memberId so downstream consumers can address it.
199	        notifyLogger.info("welcome: owner id={} memberId={}", owner.getId(), owner.getMemberId());
200	        headers.setLocation(UriComponentsBuilder.newInstance()
